-- ==============================================================================
-- PHENMO EVENTS — SUPABASE SEED DATA
-- ==============================================================================
-- Run this script in the Supabase SQL Editor after running schema.sql.
-- It populates all 7 departments, all 538 consolidated inventory assets,
-- default staff accounts, and initial events.
-- ==============================================================================

-- 1. STAFF ACCOUNTS
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, role = EXCLUDED.role, email = EXCLUDED.email, password = EXCLUDED.password;

-- 2. INVENTORY CATEGORIES (7 DEPARTMENTS)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sort_order = EXCLUDED.sort_order;

-- 3. INVENTORY ITEMS (538 CONSOLIDATED ROWS REPRESENTING 776 ASSETS)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category_id = EXCLUDED.category_id, available = EXCLUDED.available, status = EXCLUDED.status, notes = EXCLUDED.notes, model = EXCLUDED.model, serial_number = EXCLUDED.serial_number, serials = EXCLUDED.serials, sub_category = EXCLUDED.sub_category, condition = EXCLUDED.condition, location = EXCLUDED.location;

-- 4. EVENTS & PRODUCTIONS
ON CONFLICT (id) DO UPDATE SET event_name = EXCLUDED.event_name, client_name = EXCLUDED.client_name, event_date = EXCLUDED.event_date, venue = EXCLUDED.venue, status = EXCLUDED.status;
